// Generated by client/skip/sync-sources.sh from the canonical iOS sources.
import SwiftUI

/// Renders host-declared actions without assuming any platform shortcut. The
/// disabled state and reason come from the snapshot; the view never invents an
/// action or marks one available on its own.
struct CapabilityControlsView: View {
    let snapshot: CapabilitySnapshot
    let onInvoke: (String) -> Void

    var body: some View {
        VStack(alignment: .leading, spacing: 10) {
            HStack(alignment: .firstTextBaseline) {
                Text("Host actions")
                    .font(.headline)
                    .foregroundStyle(.white)
                Spacer()
                Text("rev \(snapshot.capabilityRevision)")
                    #if SKIP
                    .font(.caption)
                    #else
                    .font(.caption.monospacedDigit())
                    #endif
                    .foregroundStyle(VistaPalette.subtleText)
            }

            ForEach(snapshot.actions, id: \.id) { action in
                Button {
                    onInvoke(action.id)
                } label: {
                    VStack(alignment: .leading, spacing: 3) {
                        Text(action.presentation.label)
                            .font(.subheadline.weight(.semibold))
                            .foregroundStyle(.white)
                        Text(hint(for: action))
                            .font(.caption2)
                            .foregroundStyle(VistaPalette.subtleText)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(10)
                    .background(VistaPalette.surface, in: RoundedRectangle(cornerRadius: 12))
                }
                .buttonStyle(.plain)
                .disabled(!action.isSelectable)
                .accessibilityHint(hint(for: action))
            }

            Text("Demo capability set — no host is paired and no native action runs.")
                .font(.caption2)
                .foregroundStyle(VistaPalette.subtleText)
        }
        .padding(14)
        .background(VistaPalette.elevated.opacity(0.55), in: RoundedRectangle(cornerRadius: 16))
    }

    private func hint(for action: CapabilityAction) -> String {
        if !action.supported {
            return action.reason ?? "Unavailable on this backend"
        }
        if !action.enabled {
            return action.reason ?? "Temporarily unavailable"
        }
        switch action.authorization {
        case .granted:
            return "Allowed by host"
        case .required:
            return "Permission required"
        case .denied:
            return action.reason ?? "Permission denied"
        case .revoked:
            return action.reason ?? "Permission revoked"
        }
    }
}
